/**
 * Expansion module contract (F1). See docs/EXPANSIONS.md — that file is the spec; keep both in
 * sync. Owned by the framework: expansion agents implement these interfaces in their own folder
 * (src/expansions/<id>/engine) and do not edit this file.
 */
import type { LegalGenerator } from '../actions/common';
import type { MapDef } from '../maps';
import type { Rng } from '../rng';
import type {
  Action,
  ActionOf,
  ActionResult,
  BaseActionType,
  BuildingKind,
  DevCardCounts,
  EdgeId,
  ExpansionAction,
  ExpansionActionType,
  ExpansionId,
  GainSource,
  GameSettings,
  LossSink,
  GameState,
  HexId,
  MapId,
  ModeId,
  Phase,
  PlayerId,
  Resource,
  ResourceCounts,
  ScenarioId,
  VertexId,
} from '../types';

/** How the core paid a production roll (the `production` hook's `ctx`). */
export interface ProductionContext {
  /** Cards per city: 2, or 1 under the Epidemic event card (settings.eventCards). */
  cityYield: number;
  /** The hex that does not produce (the robber's), or null without a robber. */
  blocked: HexId | null;
}

/** A named share of an expansion's public VP (statistics screen): "Metropolis", 4. */
export interface VictoryPointPart {
  label: string;
  vp: number;
}

export interface TerrainInfo {
  kind: 'land' | 'sea' | 'fog';
  /** Display name (HUD, previews). */
  name: string;
  /** Colour of the hex in the setup screen's map thumbnails ('#rrggbb'); default grey. */
  color?: string;
}

export interface Supply {
  bankPerResource: number;
  devDeck: Readonly<DevCardCounts>;
}

/** Handler of a namespaced expansion action. Validate every field: actions may come from anywhere. */
export type ExtHandler = {
  bivarianceHack(draft: GameState, action: ExpansionAction): ActionResult;
}['bivarianceHack'];

/** Wraps a base handler. Call `next(draft, action)` to run the base rule (or the previous wrapper). */
export type Override<K extends BaseActionType> = (
  draft: GameState,
  action: ActionOf<K>,
  next: (draft: GameState, action: ActionOf<K>) => ActionResult,
) => ActionResult;

/** A typed per-expansion setting, shown on the setup screen, stored in settings.options[id][key]. */
export type OptionDef =
  | {
      key: string;
      label: string;
      description?: string;
      type: 'boolean';
      default: boolean;
      /** Added to the default VP target while on (T&B Harbormaster: +1). */
      vpBonus?: number;
    }
  | {
      key: string;
      label: string;
      description?: string;
      type: 'int';
      default: number;
      min: number;
      max: number;
    }
  | {
      key: string;
      label: string;
      description?: string;
      type: 'choice';
      default: string;
      choices: readonly { value: string; label: string }[];
    };

export interface PlayerRange {
  min: number;
  max: number;
}

export interface ScenarioDef {
  /** '<expansionId>/<name>'. */
  id: ScenarioId;
  name: string;
  blurb: string;
  players: PlayerRange;
  /** The map for a player count (must be in the scenario's player range). */
  mapFor(players: number): MapId;
  /** Every map the scenario can use (validation, previews). */
  maps: readonly MapId[];
  /** Default VP target (the setup screen and createGame start from it). Default 10. */
  vpToWin?: number;
}

/**
 * 'ready' = shown on the setup screen; 'wip' / 'demo' = only with ?modes=all (and in the sim).
 * The base mode is always first and the default.
 */
export type ModeStatus = 'ready' | 'wip' | 'demo';

export interface ModeDef {
  /** Unique. The bare expansion id for an expansion's own mode; combos like 'seafarers+ck'. */
  id: ModeId;
  name: string;
  blurb: string;
  status: ModeStatus;
  /**
   * Expansions the mode activates (requires are added automatically). Combinations exist ONLY as
   * modes: official combos are per scenario (docs/rules/scenarios-and-combos.md part C), so a
   * combo mode lists exactly the suitable scenarios.
   */
  expansions: readonly ExpansionId[];
  /** Scenario ids offered, first = default. [] = the base maps. */
  scenarios: readonly ScenarioId[];
  players: PlayerRange;
  /** VP target when the game has no scenario (C&K on the base maps: 13). Default 10. */
  vpToWin?: number;
  /** Added to the scenario's VP target (Seafarers + C&K: +2, E&P + C&K: +5). */
  vpBonus?: number;
  /** Exact VP target per scenario, overriding scenario target + vpBonus (T&B + C&K: 13 / 15). */
  scenarioVp?: Readonly<Record<ScenarioId, number>>;
}

/** Pure functions the core rules call (docs/EXPANSIONS.md §5). All optional. */
export interface ExpansionHooks {
  /** first-wins. Kind of building placed at setup step `index` (default settlement). */
  setupBuilding?(state: GameState, index: number): BuildingKind | undefined;
  /** first-wins. The two numbered dice of a roll (store any extra die in your slice). */
  rollDice?(draft: GameState): [number, number] | undefined;
  /**
   * additive. After the roll is logged, before the 7 / production branch. Return a Phase to
   * interrupt (C&K barbarian pillage choices): the roll then stops there, and your module calls
   * `continueRoll(draft)` (actions/turn.ts) when its phase is done. First returned phase wins.
   */
  onRoll?(draft: GameState, roll: number): Phase | undefined;
  /** first-wins. Phase to enter on a 7 instead of discard / moveRobber. `pending` = base discards. */
  onSeven?(draft: GameState, pending: readonly number[]): Phase | undefined;
  /**
   * additive. Mutate what each player is owed for `roll`, before the bank-shortage rule. `ctx`
   * says how the core paid: cards per city (1 under the Epidemic event card) and the hex the
   * robber blocks (null without a robber, settings.robberMode 'none').
   */
  production?(state: GameState, roll: number, owed: ResourceCounts[], ctx: ProductionContext): void;
  /**
   * first-wins. Phase to enter after production instead of main. `paid` = the resources each
   * player just received from the core production (after the bank-shortage rule).
   */
  afterProduction?(
    draft: GameState,
    roll: number,
    paid: readonly ResourceCounts[],
  ): Phase | undefined;
  /** chained. Cost of `item` ('road', 'settlement', 'city', 'devCard' or '<id>/<item>'). */
  cost?(
    state: GameState,
    item: string,
    base: ResourceCounts | undefined,
  ): ResourceCounts | undefined;
  /** chained. Supply of `kind` ('road', 'settlement', 'city' or '<id>/<piece>') per player. */
  pieceLimit?(state: GameState, player: PlayerId, kind: string, base: number): number;
  /** additive OR. Vertex occupied by a module piece (blocks settlements and the distance rule). */
  vertexBlocked?(state: GameState, v: VertexId): boolean;
  /** additive OR. Edge occupied by a module piece (blocks roads). */
  edgeBlocked?(state: GameState, e: EdgeId): boolean;
  /**
   * additive OR. A module piece on `v` cuts `player`'s route there, like an opponent's building:
   * no road may be extended through it and it breaks Longest Road (C&K: foreign knights).
   */
  blocksRoute?(state: GameState, v: VertexId, player: PlayerId): boolean;
  /** chained. Cards in hand for the 7 rule and steal candidates (C&K: + commodities). */
  handSize?(state: GameState, player: PlayerId, base: number): number;
  /** chained. On a 7, hands above this discard half (C&K: +2 per city wall). */
  discardLimit?(state: GameState, player: PlayerId, base: number): number;
  /**
   * chained. Bank stock and dev deck (C&K: no dev cards). Read via supplyOf(state). Depends on
   * settings only (createGame calls it before the state exists).
   */
  supply?(state: Pick<GameState, 'settings'>, base: Supply): Supply;
  /**
   * additive. Extra VP: `public` is visible to all, `hidden` only counts for victory. `parts`
   * (optional) names where the public VP come from, for the statistics screen.
   */
  victoryPoints?(
    state: GameState,
    player: PlayerId,
  ): { public: number; hidden?: number; parts?: VictoryPointPart[] };
  /**
   * first-wins. Statistics (UX2): which source / sink a hand change of `player` made by one of
   * your actions counts as (default 'other'). `gain` for cards received, `loss` for cards given.
   * `state` is the state the action was applied to (its phase says what was being resolved).
   */
  statsCategory?(
    state: GameState,
    action: ExpansionAction,
    player: PlayerId,
  ): { gain?: GainSource; loss?: LossSink } | undefined;
  /** chained. Bank / harbour ratio for giving `resource`. */
  bankTradeRatio?(state: GameState, player: PlayerId, resource: Resource, base: number): number;
  /** chained. Length for Longest Road (Seafarers: trade route). */
  roadLength?(state: GameState, player: PlayerId, base: number): number;
  /** additive. `player` ended their turn (before the special build phase / next turn). */
  onEndTurn?(draft: GameState, player: PlayerId): void;
  /** additive. `player`'s turn starts (preRoll). Not called for the first turn after setup. */
  onStartTurn?(draft: GameState, player: PlayerId): void;
  /** additive. After every successful action's handler, before awards and victory. */
  afterAction?(draft: GameState, action: Action): void;
  /**
   * additive OR. `true` = the core victory check (VP target on your own turn) does nothing in this
   * state; the module declares winners itself, usually from `afterAction` (Oil Springs: the win is
   * checked at the end of the turn, after the disaster phase).
   */
  deferVictory?(state: GameState): boolean;
}

export interface ExpansionModule {
  /** = folder name in src/expansions, no '/'. */
  id: ExpansionId;
  name: string;
  /** Activated automatically with this module. */
  requires?: readonly ExpansionId[];
  /** Officially impossible together (E&P vs Seafarers). Symmetric: either side may declare it. */
  conflicts?: readonly ExpansionId[];
  /**
   * A small rules variant (friendly robber, house rules) that may be added on top of any mode
   * via `config.expansions`. Non-variant modules only come in through a mode.
   */
  variant?: boolean;
  players?: PlayerRange;
  /**
   * Your namespaced terrains ('ep/fishShoal'). `kind` drives the core rules: settlements need a
   * vertex touching a 'land' hex; 'sea' / 'fog' hexes never produce in the core.
   */
  terrains?: Readonly<Record<string, TerrainInfo>>;
  maps?: readonly MapDef[];
  scenarios?: readonly ScenarioDef[];
  modes?: readonly ModeDef[];
  options?: readonly OptionDef[];
  /**
   * Reject bad settings combinations (createGame throws the message): e.g. T&B event cards with
   * balancedDice. Runs after options are resolved.
   */
  validate?(settings: GameSettings): string | null;
  /** Create `draft.ext[id]` (and adjust the fresh state if needed). Runs at the end of createGame. */
  init?(draft: GameState, rng: Rng): void;
  /** Faster deep copy of your slice for action drafts (default: cloneJson). */
  cloneExt?(slice: unknown): unknown;
  /** Handlers of your namespaced action types. */
  actions?: Readonly<Record<ExpansionActionType, ExtHandler>>;
  /** Wrappers around base action handlers. Pair every rejection with filterLegal. */
  overrides?: { readonly [K in BaseActionType]?: Override<K> };
  /** Extra legal actions (any phase). Must be sound. */
  legal?: LegalGenerator;
  /** Drop / replace legal actions (runs after every generator, in settings order). */
  filterLegal?(state: GameState, actions: Action[]): Action[];
  /** Your action types that add roads or occupy vertices (Longest Road is then recomputed). */
  changesRoads?: readonly ExpansionActionType[];
  /** Who may act in your phases (undefined = not my phase / default turn.current). */
  actors?(state: GameState): PlayerId[] | undefined;
  hooks?: ExpansionHooks;
}
